import type { Transition } from "motion/react";

export const easeOut = [0.23, 1, 0.32, 1] as const;

export const easeInOut = [0.77, 0, 0.175, 1] as const;

export const easeOutClass = "ease-[cubic-bezier(0.23,1,0.32,1)]";

export const duration = {
  fast: 0.14,
  base: 0.2,
  slow: 0.28,
} as const;

export const springSnappy = {
  type: "spring",
  duration: 0.24,
  bounce: 0,
} as const satisfies Transition;

export const springLayout = {
  type: "spring",
  duration: 0.3,
  bounce: 0,
} as const satisfies Transition;

export function transitionFor(
  reduceMotion: boolean | null,
  transition: Transition,
): Transition {
  return reduceMotion ? { duration: 0 } : transition;
}

export function edgeOffset(placement: string | null, distance: number) {
  switch (placement) {
    case "top":
      return { x: 0, y: distance };
    case "left":
      return { x: distance, y: 0 };
    case "right":
      return { x: -distance, y: 0 };
    default:
      return { x: 0, y: -distance };
  }
}

import { type CnOptions, cn as mergeClasses } from "tailwind-variants";

export function cn(...classes: CnOptions): string {
  return mergeClasses(...classes) ?? "";
}

import { tv, type VariantProps } from "tailwind-variants";

export const buttonStyles = tv({
  base: "inline-flex shrink-0 cursor-default items-center justify-center gap-2 whitespace-nowrap rounded-md font-medium tracking-[-0.01em] transition-[color,background-color,border-color,box-shadow,scale] duration-150 ease-[cubic-bezier(0.23,1,0.32,1)] disabled:cursor-default disabled:opacity-50 disabled:shadow-none focus-visible:outline-2 focus-visible:outline-offset-3 focus-visible:outline-ring [&_svg]:pointer-events-none [&_svg]:shrink-0",
  variants: {
    variant: {
      default:
        "bg-primary text-primary-foreground shadow-[var(--shadow-card)] hover:bg-primary/90 pressed:bg-primary/90",
      secondary:
        "bg-secondary text-secondary-foreground hover:bg-border/70 pressed:bg-border/70",
      outline:
        "border border-border bg-card text-foreground shadow-[var(--shadow-card)] hover:bg-muted pressed:bg-muted",
      ghost:
        "text-foreground hover:bg-muted pressed:bg-muted aria-[pressed=true]:bg-accent aria-[pressed=true]:text-accent-foreground aria-[pressed=true]:hover:bg-accent",
      minimal:
        "text-muted-foreground hover:bg-muted hover:text-foreground pressed:bg-muted pressed:text-foreground",
      destructive:
        "bg-destructive text-background shadow-[var(--shadow-card)] hover:bg-destructive/90 pressed:bg-destructive/90",
    },
    size: {
      default: "h-11 px-5 text-sm",
      sm: "h-9 px-3.5 text-sm",
      lg: "h-12 px-6 text-sm",
      icon: "size-11 cursor-pointer p-0",
    },
  },
  defaultVariants: { variant: "default", size: "default" },
});

export const buttonLinkStyles = tv({
  extend: buttonStyles,
  base: "cursor-pointer",
});

export type ButtonVariant = NonNullable<
  VariantProps<typeof buttonStyles>["variant"]
>;
export type ButtonSize = NonNullable<VariantProps<typeof buttonStyles>["size"]>;

"use client";

import { type MotionProps, motion, useReducedMotion } from "motion/react";
import {
  Button as AriaButton,
  type ButtonProps as AriaButtonProps,
  composeRenderProps,
} from "react-aria-components";
import { springLayout } from "./motion";
import {
  type ButtonSize,
  type ButtonVariant,
  buttonStyles,
} from "./button-styles";

export interface ButtonProps
  extends Omit<
    AriaButtonProps,
    | "style"
    | "onAnimationStart"
    | "onAnimationEnd"
    | "onAnimationIteration"
    | "onHoverStart"
    | "onHoverEnd"
  > {
  ref?: React.Ref<HTMLButtonElement>;
  variant?: ButtonVariant;
  size?: ButtonSize;
  static?: boolean;
  layout?: MotionProps["layout"];
}

const MotionButton = motion.create(AriaButton);

const pressStyles = "motion-safe:pressed:not-aria-expanded:scale-[0.96]";

export function Button({
  className,
  variant = "default",
  size = "default",
  static: isStatic = false,
  layout,
  ...props
}: ButtonProps) {
  const reduceMotion = useReducedMotion();
  return (
    <MotionButton
      data-slot="button"
      data-variant={variant}
      data-size={size}
      layout={reduceMotion ? false : layout}
      transition={springLayout}
      className={composeRenderProps(className, (className) =>
        buttonStyles({
          variant,
          size,
          className: [!isStatic && pressStyles, className],
        }),
      )}
      {...props}
    />
  );
}

"use client";

import { XIcon } from "@phosphor-icons/react";
import { type HTMLMotionProps, motion, useReducedMotion } from "motion/react";
import {
  createContext,
  type ReactNode,
  useContext,
  useState,
  useSyncExternalStore,
} from "react";
import {
  Dialog as AriaDialog,
  type DialogProps as AriaDialogProps,
  DialogTrigger as AriaDialogTrigger,
  composeRenderProps,
  type DialogTriggerProps,
  Heading,
  type HeadingProps,
  Modal,
  ModalOverlay,
  type ModalOverlayProps,
  Text,
  type TextProps,
} from "react-aria-components";
import { cn } from "./utils";
import { Button, type ButtonProps } from "./button";

type DialogAnimation = "unmounted" | "hidden" | "visible";

const mobileQuery = "(max-width: 639px)";

function subscribeToMobile(onChange: () => void) {
  const media = window.matchMedia(mobileQuery);
  media.addEventListener("change", onChange);
  return () => media.removeEventListener("change", onChange);
}

function isMobileViewport() {
  return window.matchMedia(mobileQuery).matches;
}

const CloseContext = createContext<(() => void) | null>(null);
const DialogAnimationContext = createContext<{
  animation: DialogAnimation;
  complete: (state: string) => void;
}>({ animation: "unmounted", complete: () => {} });

export function Dialog({
  defaultOpen,
  isOpen,
  onOpenChange,
  ...props
}: DialogTriggerProps) {
  const [animation, setAnimation] = useState<DialogAnimation>(
    defaultOpen || isOpen ? "visible" : "unmounted",
  );
  const [previousIsOpen, setPreviousIsOpen] = useState(isOpen);

  if (isOpen !== previousIsOpen) {
    setPreviousIsOpen(isOpen);
    if (isOpen !== undefined) setAnimation(isOpen ? "visible" : "hidden");
  }

  return (
    <DialogAnimationContext.Provider
      value={{
        animation,
        complete: (state) => {
          if (state === "hidden") {
            setAnimation((current) =>
              current === "hidden" ? "unmounted" : current,
            );
          }
        },
      }}
    >
      <AriaDialogTrigger
        {...props}
        defaultOpen={defaultOpen}
        isOpen={isOpen}
        onOpenChange={(open) => {
          if (isOpen === undefined) setAnimation(open ? "visible" : "hidden");
          onOpenChange?.(open);
        }}
      />
    </DialogAnimationContext.Provider>
  );
}

export function DialogTrigger({ className, ...props }: ButtonProps) {
  return <Button {...props} data-slot="dialog-trigger" className={className} />;
}

export interface DialogContentProps extends Omit<AriaDialogProps, "children"> {
  ref?: React.Ref<HTMLElement>;
  children: ReactNode;
  overlayProps?: Omit<ModalOverlayProps, "children" | "render" | "isExiting">;
  modalProps?: Omit<React.ComponentProps<typeof Modal>, "children" | "render">;
  modalSlot?: string;
}

export function DialogContent({
  children,
  className,
  overlayProps,
  modalProps,
  modalSlot = "dialog-modal",
  ...props
}: DialogContentProps) {
  const reduceMotion = useReducedMotion();
  const isMobile = useSyncExternalStore(
    subscribeToMobile,
    isMobileViewport,
    () => false,
  );
  const { animation, complete } = useContext(DialogAnimationContext);
  return (
    <ModalOverlay
      {...overlayProps}
      isDismissable={
        props.role === "alertdialog"
          ? false
          : (overlayProps?.isDismissable ?? true)
      }
      isExiting={animation === "hidden"}
      data-slot="dialog-overlay"
      className={composeRenderProps(overlayProps?.className, (className) =>
        cn(
          "fixed inset-x-0 top-0 z-50 grid h-[var(--visual-viewport-height,100dvh)] items-end overflow-y-auto sm:place-items-center sm:p-4",
          className,
        ),
      )}
    >
      <motion.div
        aria-hidden="true"
        data-slot="dialog-backdrop"
        className="pointer-events-none fixed inset-0 bg-foreground/40 backdrop-blur-sm dark:bg-foreground/20"
        initial={{ opacity: 0 }}
        animate={{ opacity: animation === "hidden" ? 0 : 1 }}
        transition={{
          duration: reduceMotion ? 0.12 : animation === "hidden" ? 0.16 : 0.24,
          ease: [0.23, 1, 0.32, 1],
        }}
      />
      <Modal
        {...modalProps}
        render={(domProps) => (
          <motion.div
            {...(domProps as HTMLMotionProps<"div">)}
            initial={
              reduceMotion
                ? { opacity: 0 }
                : isMobile
                  ? { opacity: 0, y: "100%" }
                  : { opacity: 0, y: 12, scale: 0.96 }
            }
            animate={
              animation === "hidden"
                ? reduceMotion
                  ? { opacity: 0 }
                  : isMobile
                    ? { opacity: 0, y: "100%", scale: 1 }
                    : { opacity: 0, y: 6, scale: 0.985 }
                : { opacity: 1, y: isMobile ? "0%" : 0, scale: 1 }
            }
            transition={{
              duration: reduceMotion
                ? 0.12
                : isMobile
                  ? animation === "hidden"
                    ? 0.24
                    : 0.32
                  : animation === "hidden"
                    ? 0.18
                    : 0.26,
              ease: [0.23, 1, 0.32, 1],
            }}
            onAnimationComplete={() => {
              if (animation === "hidden") complete("hidden");
            }}
          />
        )}
        data-slot={modalSlot}
        className={cn(
          "relative max-h-[calc(var(--visual-viewport-height,100dvh)-1rem)] w-full min-w-0 max-w-full overflow-y-auto overscroll-contain rounded-t-2xl bg-card p-6 pb-[max(1.5rem,env(safe-area-inset-bottom))] text-card-foreground shadow-[var(--shadow-float)] outline-none ring-1 ring-border/70 sm:max-h-[calc(var(--visual-viewport-height,100dvh)-2rem)] sm:max-w-md sm:rounded-xl sm:p-7",
          modalProps?.className,
        )}
      >
        <AriaDialog
          {...props}
          data-slot="dialog-content"
          className={cn("outline-none", className)}
        >
          {({ close }) => (
            <CloseContext.Provider value={close}>
              {children}
            </CloseContext.Provider>
          )}
        </AriaDialog>
      </Modal>
    </ModalOverlay>
  );
}

export function DialogHeader({
  className,
  ...props
}: React.HTMLAttributes<HTMLDivElement>) {
  return (
    <div
      {...props}
      data-slot="dialog-header"
      className={cn("flex items-start justify-between gap-4", className)}
    />
  );
}

export function DialogTitle({ className, ...props }: HeadingProps) {
  return (
    <Heading
      {...props}
      slot="title"
      data-slot="dialog-title"
      className={cn("text-xl font-semibold tracking-[-0.04em]", className)}
    />
  );
}

export function DialogDescription({ className, ...props }: TextProps) {
  return (
    <Text
      {...props}
      slot="description"
      data-slot="dialog-description"
      className={cn(
        "mt-2 block text-sm leading-6 text-muted-foreground",
        className,
      )}
    />
  );
}

export function DialogFooter({
  className,
  ...props
}: React.HTMLAttributes<HTMLDivElement>) {
  return (
    <div
      {...props}
      data-slot="dialog-footer"
      className={cn("mt-6 flex justify-end gap-2", className)}
    />
  );
}

export function DialogClose({
  className,
  children,
  onPress,
  ...props
}: ButtonProps) {
  const close = useContext(CloseContext);
  return (
    <Button
      {...props}
      data-slot="dialog-close"
      variant={props.variant ?? "ghost"}
      size={props.size ?? (children ? "default" : "icon")}
      aria-label={
        props["aria-label"] ?? (children ? undefined : "Close dialog")
      }
      onPress={(event) => {
        onPress?.(event);
        close?.();
      }}
      className={className}
    >
      {children ?? <XIcon size={17} aria-hidden="true" />}
    </Button>
  );
}
